from author_common import *

MODEL = 'FE Reference Handbook 10.0.1, Ethics and Professional Practice, Model Rules of Professional Conduct'

dump('math', [
 q('math-0001', 'math-a', 'mcq', 'A straight line passes through the points (2, 3) and (6, 11). What is its y-intercept?',
   'b', 'Slope is how much the line climbs for each step to the right. Find the slope, then walk the line back to x = 0 and see where it lands.',
   'Slope m = \\frac{11 - 3}{6 - 2} = 2.\n\nUse y = mx + b at the point (2, 3): 3 = 2(2) + b, so b = -1.',
   hb('Mathematics'), units=None, tags=['line', 'slope', 'intercept'], options=opts('-3', '-1', '1', '2')),
 q('math-0002', 'math-b', 'numeric', 'Find the area between the curve y = 3x^{2} and the x-axis from x = 0 to x = 2.',
   num(8, 'square units'), 'Integration adds up thin vertical strips under the curve. The antiderivative is the running total, so you read it at the end and subtract what it was at the start.',
   'The antiderivative of 3x^{2} is x^{3}.\n\nArea = 2^{3} - 0^{3} = 8.',
   hb('Mathematics'), units=None, tags=['integral', 'area']),
 q('math-0003', 'math-c', 'mcq', 'Vectors **A** = 3**i** + 4**j** and **B** = 4**i** - 3**j** lie in the same plane. What is the angle between them?',
   'd', 'The dot product measures how much two arrows point the same way. A dot product of zero means they share no direction at all: they meet at a right angle.',
   '**A** · **B** = (3)(4) + (4)(-3) = 0.\n\ncos(angle) = \\frac{A · B}{|A||B|} = 0, so the angle is 90°.',
   hb('Mathematics'), units=None, tags=['dot product', 'vectors'], options=opts('0°', '45°', '60°', '90°')),
 q('math-0004', 'math-d', 'mcq', 'A sample of five measurements is 2, 4, 4, 6 and 9. What is the sample standard deviation?',
   'b', 'Standard deviation is the typical distance of each value from the average. For a sample you divide by one less than the count, because a small sample tends to understate the spread.',
   'Mean = \\frac{2 + 4 + 4 + 6 + 9}{5} = 5.\n\nSquared distances from the mean: 9, 1, 1, 1 and 16, which add to 28.\n\ns = \\sqrt{\\frac{28}{5 - 1}} = \\sqrt{7} = 2.65.\n\nDividing by 5 instead of 4 gives 2.37, which is the population value.',
   hb('Engineering Probability and Statistics'), units=None, tags=['standard deviation', 'statistics'], options=opts('2.37', '2.65', '5.60', '7.00')),
 q('math-0005', 'math-d', 'multi', 'Which statements about a normal distribution are true? Select the two that apply.',
   ['a', 'b'], 'A normal distribution is the bell curve. It is perfectly balanced around its middle, and most values sit close to that middle.',
   'The bell curve is symmetric with one peak, so its mean, median and mode are the same value. About 68% of values fall within one standard deviation of the mean.\n\nIt is not skewed, it extends to negative values, and its variance is a separate parameter from its mean.',
   hb('Engineering Probability and Statistics'), verify='reference', basis='FE Reference Handbook 10.0.1, Engineering Probability and Statistics, normal distribution. The 68% figure is also recomputed from the normal curve.',
   units=None, tags=['normal distribution', 'bell curve'], selectCount=2,
   options=opts('Its mean, median and mode are equal', 'About 68% of values fall within one standard deviation of the mean', 'It is skewed to the right', 'Its variance always equals its mean', 'It can only take positive values')),
])

dump('ethics', [
 q('ethics-0001', 'ethics-a', 'mcq', 'An engineer tells a client that a retaining wall design is unsafe. The client overrules the engineer and orders construction to proceed as drawn. Under the NCEES Model Rules, what must the engineer do?',
   'b', 'Keeping people safe outranks keeping the client happy. If you are overruled and someone could get hurt, you have to tell someone who can stop it.',
   'The first duty in the Model Rules is to the public. When an engineer\'s judgment is overruled in a way that endangers health, safety or welfare, the engineer must notify the client or employer and any other authority that may be appropriate.\n\nProceeding, working around the client in secret, or walking away silently all leave the hazard in place.',
   hb('Ethics and Professional Practice'), verify='reference', basis=MODEL + ': obligation to the public', units=None, tags=['public safety', 'model rules'],
   options=opts('Proceed, because the client carries the liability once informed', 'Notify the client and any other authority that may be appropriate', 'Quietly strengthen the design without telling the client', 'Resign from the project and say nothing further')),
 q('ethics-0002', 'ethics-c', 'mcq', 'A licensed engineer is asked to sign and seal drawings that were produced by another firm. She did not supervise or review the work. May she seal them?',
   'c', 'A seal is a promise that says "I was in charge of this and I stand behind it." You cannot make that promise about work you did not direct.',
   'The Model Rules allow a licensee to seal only work in their area of competence that was prepared under their responsible charge, meaning their direct control and personal supervision.\n\nBeing licensed in the state, being indemnified or having the client\'s approval does not change who was in charge of the work.',
   hb('Ethics and Professional Practice'), verify='reference', basis=MODEL + ': signing and sealing; Model Law definition of responsible charge', units=None, tags=['seal', 'responsible charge', 'licensure'],
   options=opts('Yes, if she is licensed in that state', 'Yes, if the other firm indemnifies her', 'No, because the work was not prepared under her responsible charge', 'No, unless the client approves in writing')),
 q('ethics-0003', 'ethics-a', 'mcq', 'An engineer designing a pump station for a city is offered a paid consulting role by the pump supplier on the same project. When may the engineer accept both payments?',
   'c', 'Being paid by two sides of the same deal is only fair if nobody is kept in the dark. Everyone involved has to know and say yes.',
   'The Model Rules bar compensation from more than one party for services on the same project unless the circumstances are fully disclosed and agreed to in writing by all interested parties.\n\nThe engineer\'s own belief that the design will not be affected is not enough, and there is no dollar threshold.',
   hb('Ethics and Professional Practice'), verify='reference', basis=MODEL + ': obligation to employers and clients', units=None, tags=['conflict of interest', 'compensation'],
   options=opts('Never', 'When the supplier\'s fee is below a set dollar limit', 'When the circumstances are fully disclosed and all interested parties agree in writing', 'When the engineer judges that it will not affect the design')),
 q('ethics-0004', 'ethics-c', 'mcq', 'A professional engineer licensed in one state wants to offer engineering services in a second state. Which route does the NCEES Model Law provide for someone who already holds a license elsewhere?',
   'b', 'A license only works in the state that issued it. The second state can recognize what you already earned instead of making you start over.',
   'Licensure by comity lets a board license an engineer who holds a license from another jurisdiction with comparable requirements.\n\nA home-state license does not carry over on its own, and the FE exam and intern status are steps before a first license.',
   hb('Ethics and Professional Practice'), verify='reference', basis='FE Reference Handbook 10.0.1, Ethics and Professional Practice, Model Law: licensure by comity', units=None, tags=['licensure', 'comity'],
   options=opts('Practice under the home-state license for up to one year', 'Licensure by comity', 'Retake the FE exam', 'Register as an engineer intern')),
])

dump('econ', [
 q('econ-0001', 'econ-a', 'mcq', '$5,000 is deposited in an account that pays 6% interest compounded annually. What is the balance after 10 years?',
   'b', 'Each year you earn interest on last year\'s interest too, so the pile grows a little faster every year.',
   'F = P(1 + i)^{n} = 5,000(1.06)^{10} = 5,000 × 1.7908 = $8,954.\n\n$8,000 is what simple interest would give.',
   hb('Engineering Economics'), units=None, tags=['future worth', 'compound interest'], options=opts('$8,000', '$8,954', '$9,097', '$10,600')),
 q('econ-0002', 'econ-a', 'numeric', 'A $20,000 loan is repaid in five equal end-of-year payments at 8% annual interest. What is each payment?',
   num(5009, '$ per year'), 'Each payment covers that year\'s interest plus a slice of the loan. The capital recovery factor spreads the loan evenly so the last payment clears it exactly.',
   'A = P × \\frac{i(1 + i)^{n}}{(1 + i)^{n} - 1} = 20,000 × \\frac{0.08(1.08)^{5}}{(1.08)^{5} - 1} = 20,000 × 0.2505 = $5,009.',
   hb('Engineering Economics'), units=None, tags=['capital recovery', 'loan payment']),
 q('econ-0003', 'econ-c', 'mcq', 'A plant has fixed costs of $120,000 per year. Each unit costs $18 to make and sells for $30. How many units per year must be sold to break even?',
   'c', 'Every unit sold leaves a little money after paying for itself. Break-even is the number of units whose leftovers add up to the bills you pay no matter what.',
   'Each unit contributes 30 - 18 = $12 toward fixed costs.\n\nBreak-even quantity = \\frac{120,000}{12} = 10,000 units.',
   hb('Engineering Economics'), units=None, tags=['break-even'], options=opts('4,000', '6,667', '10,000', '12,000')),
 q('econ-0004', 'econ-d', 'mcq', 'A project has a 20% chance of losing $50,000, a 50% chance of earning $40,000 and a 30% chance of earning $100,000. What is its expected value?',
   'b', 'Expected value is the average result if you could run the project many times. Weight each outcome by how often it happens and add them up.',
   'EV = 0.20(-50,000) + 0.50(40,000) + 0.30(100,000) = -10,000 + 20,000 + 30,000 = $40,000.',
   hb('Engineering Economics'), units=None, tags=['expected value', 'risk'], options=opts('$30,000', '$40,000', '$45,000', '$90,000')),
])

dump('statics', [
 q('statics-0001', 'statics-a', 'numeric', 'A 100 N force acts along the positive x-axis. An 80 N force acts at the same point, 60° above the positive x-axis. What is the magnitude of the resultant?',
   num(156.2, 'N'), 'Break each push into a sideways part and an upward part. Add the sideways parts, add the upward parts, then use the right-triangle rule to get the single push that does the same job.',
   'R_{x} = 100 + 80 cos 60° = 140 N.\n\nR_{y} = 80 sin 60° = 69.3 N.\n\nR = \\sqrt{140^{2} + 69.3^{2}} = 156.2 N.',
   hb('Statics'), tags=['resultant', 'components']),
 q('statics-0002', 'statics-c', 'mcq', 'A simply supported beam spans 6 m between a pin at A and a roller at B. A single 30 kN load acts 2 m from A. What is the vertical reaction at A?',
   'c', 'Two people carrying a plank share the weight on it. Whoever stands closer to the weight carries more of it.',
   'Take moments about A: B_{y}(6) = 30(2), so B_{y} = 10 kN.\n\nSum of vertical forces: A_{y} = 30 - 10 = 20 kN.\n\nThe load is closer to A, so A carries the larger share.',
   hb('Statics'), tags=['reactions', 'equilibrium', 'beam'], options=opts('10 kN', '15 kN', '20 kN', '30 kN')),
 q('statics-0003', 'statics-e', 'mcq', 'A T-shaped section has a flange 100 mm wide and 20 mm thick on top of a web 20 mm wide and 80 mm tall. How far is the centroid above the bottom of the web?',
   'c', 'The centroid is the balance point of the shape. Treat each rectangle as a weight sitting at its own centre, then find where the two would balance.',
   'Web: area 1,600 mm^{2}, centre 40 mm above the bottom.\n\nFlange: area 2,000 mm^{2}, centre 90 mm above the bottom.\n\nCentroid height = \\frac{1,600(40) + 2,000(90)}{1,600 + 2,000} = \\frac{244,000}{3,600} = 67.8 mm.',
   hb('Statics'), tags=['centroid', 'composite area'], options=opts('50.0 mm', '60.0 mm', '67.8 mm', '72.2 mm')),
 q('statics-0004', 'statics-g', 'mcq', 'A crate rests on a ramp. The coefficient of static friction between the crate and the ramp is 0.50. What is the steepest ramp angle at which the crate stays put?',
   'b', 'Tilt a board with a book on it. The book slides when the downhill pull beats the grip. The grip coefficient tells you the tilt where that happens.',
   'Sliding is about to start when tan(angle) = μ_{s}.\n\nAngle = tan^{-1}(0.50) = 26.6°.\n\nThe weight of the crate cancels out, so it does not matter.',
   hb('Statics'), units=None, tags=['friction', 'incline'], options=opts('22.5°', '26.6°', '30.0°', '63.4°')),
 q('statics-0005', 'statics-f', 'numeric', 'A rectangular section is 100 mm wide and 200 mm deep. What is its moment of inertia about the horizontal axis through its centroid? Give the answer in units of 10^{6} mm^{4}.',
   num(66.67, '× 10^{6} mm^{4}'), 'Moment of inertia measures how hard a shape is to bend. Material far from the middle counts far more than material near it, which is why depth is cubed.',
   'I = \\frac{bh^{3}}{12} = \\frac{100(200)^{3}}{12} = 66.67 × 10^{6} mm^{4}.',
   hb('Statics'), tags=['moment of inertia', 'rectangle']),
])

dump('dynamics', [
 q('dynamics-0001', 'dynamics-a', 'mcq', 'A car starts from rest and accelerates uniformly to 27 m/s in 9 s. How far does it travel in that time?',
   'b', 'When speed builds up steadily from zero, the average speed is half the final speed. Distance is that average speed times the time.',
   'Acceleration a = \\frac{27}{9} = 3 m/s^{2}.\n\nDistance s = \\frac{1}{2}at^{2} = \\frac{1}{2}(3)(9)^{2} = 121.5 m.\n\nCheck: average speed 13.5 m/s × 9 s = 121.5 m.',
   hb('Dynamics'), tags=['kinematics', 'constant acceleration'], options=opts('81.0 m', '121.5 m', '243.0 m', '364.5 m')),
 q('dynamics-0002', 'dynamics-c', 'numeric', 'A 50 kg crate is pulled along a level floor by a 300 N horizontal force. The coefficient of kinetic friction is 0.30. What is the acceleration of the crate? Use g = 9.81 m/s^{2}.',
   num(3.06, 'm/s^{2}'), 'Friction eats part of the pull. Whatever push is left over is what actually speeds the crate up.',
   'Normal force N = 50(9.81) = 490.5 N.\n\nFriction = 0.30(490.5) = 147.2 N.\n\nNet force = 300 - 147.2 = 152.8 N.\n\na = \\frac{152.8}{50} = 3.06 m/s^{2}.',
   hb('Dynamics'), tags=['newton second law', 'friction']),
 q('dynamics-0003', 'dynamics-d', 'mcq', 'A 2 kg ball is dropped from rest from a height of 10 m. Ignoring air resistance, how fast is it moving just before it lands? Use g = 9.81 m/s^{2}.',
   'b', 'Height is stored energy. As the ball falls, all of that stored energy turns into speed. The mass cancels out, so a heavy ball and a light ball land at the same speed.',
   'Energy balance: mgh = \\frac{1}{2}mv^{2}.\n\nv = \\sqrt{2gh} = \\sqrt{2(9.81)(10)} = 14.0 m/s.',
   hb('Dynamics'), tags=['energy', 'free fall'], options=opts('9.9 m/s', '14.0 m/s', '19.6 m/s', '98.1 m/s')),
 q('dynamics-0004', 'dynamics-b', 'mcq', 'A thin uniform rod has a mass of 6 kg and a length of 2 m. What is its mass moment of inertia about an axis through one end, perpendicular to the rod?',
   'c', 'A rod is harder to swing from its end than to spin about its middle, because more of its mass is far from the pivot.',
   'About one end: I = \\frac{mL^{2}}{3} = \\frac{6(2)^{2}}{3} = 8 kg·m^{2}.\n\nAbout the centre it would be \\frac{mL^{2}}{12} = 2 kg·m^{2}.',
   hb('Dynamics'), tags=['mass moment of inertia', 'rod'], options=opts('2 kg·m^{2}', '6 kg·m^{2}', '8 kg·m^{2}', '24 kg·m^{2}')),
])

