dump('mechmat', [
 q('mechmat-0001', 'mechmat-b', 'mcq', 'A 20 mm diameter steel rod carries a 50 kN tensile load. What is the axial stress?',
   'c', 'Stress is how hard each bit of the material is being pulled. Spread the load over the cut area, the same way pressure spreads a force over a surface.',
   'Area = \\frac{π(20)^{2}}{4} = 314.2 mm^{2}.\n\nStress = \\frac{P}{A} = \\frac{50,000 N}{314.2 mm^{2}} = 159 MPa.',
   hb('Mechanics of Materials'), tags=['axial stress'], options=opts('79.6 MPa', '125 MPa', '159 MPa', '318 MPa')),
 q('mechmat-0002', 'mechmat-c', 'numeric', 'A steel rod is 20 mm in diameter and 2 m long. It carries a 50 kN tensile load. The modulus of elasticity is 200 GPa. How much does the rod stretch?',
   num(1.59, 'mm'), 'A rod is a very stiff spring. It stretches more if you pull harder or if it is longer, and less if it is thicker or made of stiffer material.',
   'Area = 314.2 mm^{2}.\n\nStretch = \\frac{PL}{AE} = \\frac{50,000(2,000)}{314.2(200,000)} = 1.59 mm.\n\nUnits: N, mm and MPa work together.',
   hb('Mechanics of Materials'), tags=['axial deformation', 'elongation']),
 q('mechmat-0003', 'mechmat-a', 'mcq', 'A simply supported beam spans 8 m and carries a uniform load of 10 kN/m over its full length. What is the maximum bending moment?',
   'b', 'A loaded beam bends most in the middle, like a plank sagging between two chairs. That is where the bending moment peaks.',
   'For a uniform load on a simple span, the largest moment is at midspan.\n\nM_{max} = \\frac{wL^{2}}{8} = \\frac{10(8)^{2}}{8} = 80 kN·m.',
   hb('Mechanics of Materials'), tags=['bending moment', 'uniform load'], options=opts('40 kN·m', '80 kN·m', '160 kN·m', '320 kN·m')),
 q('mechmat-0004', 'mechmat-d', 'mcq', 'At a point in a plate, the normal stresses on two perpendicular faces are 80 MPa and 20 MPa, both tension. The shear stress on those faces is 40 MPa. What is the maximum principal stress?',
   'c', 'Turn the little square of material and the stresses on its faces change. At one special angle the pull is as large as it can get and the shear vanishes. That largest pull is the maximum principal stress.',
   'Mohr\'s circle centre = \\frac{80 + 20}{2} = 50 MPa.\n\nRadius = \\sqrt{(\\frac{80 - 20}{2})^{2} + 40^{2}} = \\sqrt{30^{2} + 40^{2}} = 50 MPa.\n\nMaximum principal stress = centre + radius = 100 MPa.',
   hb('Mechanics of Materials'), tags=['principal stress', 'mohr circle'], options=opts('50 MPa', '90 MPa', '100 MPa', '140 MPa')),
 q('mechmat-0005', 'mechmat-b', 'mcq', 'A rectangular beam is 100 mm wide and 200 mm deep. It carries a bending moment of 20 kN·m about its strong axis. What is the maximum bending stress?',
   'b', 'When a beam bends, the top is squeezed and the bottom is stretched. The stress is biggest at the outer edges, farthest from the middle.',
   'I = \\frac{100(200)^{3}}{12} = 66.67 × 10^{6} mm^{4}, and the outer edge is c = 100 mm from the centre.\n\nStress = \\frac{Mc}{I} = \\frac{20 × 10^{6}(100)}{66.67 × 10^{6}} = 30 MPa.',
   hb('Mechanics of Materials'), tags=['bending stress', 'flexure'], options=opts('15 MPa', '30 MPa', '60 MPa', '120 MPa')),
 q('mechmat-0006', 'mechmat-c', 'multi', 'A simply supported beam carries a uniform load. Which changes reduce its midspan deflection? Select all that apply.',
   ['a', 'b', 'c'], 'A beam sags less if the material is stiffer, the shape is deeper or the span is shorter. Span matters most of all.',
   'Midspan deflection = \\frac{5wL^{4}}{384EI}.\n\nA larger E or a larger I sits in the bottom of the fraction, so each reduces deflection. A shorter L reduces it sharply because L is raised to the fourth power.\n\nMore load increases deflection. Bending a rectangle about its weak axis lowers I, which increases deflection.',
   hb('Mechanics of Materials'), units=None, tags=['deflection', 'stiffness'],
   options=opts('Use a material with a higher modulus of elasticity', 'Use a deeper section with a larger moment of inertia', 'Shorten the span', 'Increase the load', 'Turn a rectangular section on its side so it bends about its weak axis')),
 q('mechmat-0007', 'mechmat-a', 'hotspot', 'A simply supported beam carries one point load P at a third of the span from A. Click the place on the beam where the bending moment is largest.',
   'load', 'With a single point load, the bending moment diagram is a triangle. Its peak is right under the load, not automatically at midspan.',
   'The moment is zero at both supports and rises in a straight line from each support to the load.\n\nThe two lines meet under the load, so the largest moment is there: M_{max} = \\frac{Pab}{L} with a = \\frac{L}{3} and b = \\frac{2L}{3}.',
   hb('Mechanics of Materials'), units=None, tags=['moment diagram', 'point load'],
   figure={'viewBox': '0 0 400 165', 'alt': 'A simply supported beam with a pin at A on the left and a roller at B on the right. A downward point load P acts one third of the span from A.', 'svg': BEAM},
   regions=[{'id': 'a', 'label': 'At support A', 'shape': 'rect', 'x': 18, 'y': 52, 'w': 44, 'h': 62},
            {'id': 'load', 'label': 'Under the load', 'shape': 'rect', 'x': 125, 'y': 12, 'w': 44, 'h': 78},
            {'id': 'mid', 'label': 'At midspan', 'shape': 'rect', 'x': 178, 'y': 52, 'w': 44, 'h': 38},
            {'id': 'b', 'label': 'At support B', 'shape': 'rect', 'x': 338, 'y': 52, 'w': 44, 'h': 58}]),
])

dump('materials', [
 q('materials-0001', 'materials-a', 'mcq', 'A concrete mix uses 180 kg of water and 400 kg of cement per cubic metre. What is the water-cement ratio?',
   'b', 'The water-cement ratio is how soupy the cement paste is. Less water for the same cement makes stronger, less porous concrete.',
   'w/c = \\frac{180}{400} = 0.45.\n\nThe ratio is water divided by cement, by mass.',
   hb('Civil Engineering'), tags=['concrete', 'mix design'], options=opts('0.31', '0.45', '0.55', '2.22')),
 q('materials-0002', 'materials-c', 'mcq', 'A 150 mm diameter concrete cylinder fails at a load of 530 kN in a compression test. What is the compressive strength?',
   'c', 'Strength is the load the cylinder took at failure, spread over the flat circle it was pressed on.',
   'Area = \\frac{π(150)^{2}}{4} = 17,671 mm^{2}.\n\nStrength = \\frac{530,000 N}{17,671 mm^{2}} = 30.0 MPa.',
   hb('Civil Engineering'), tags=['concrete', 'compressive strength'], options=opts('7.5 MPa', '23.6 MPa', '30.0 MPa', '45.0 MPa')),
 q('materials-0003', 'materials-b', 'match', 'Place each test on the property it measures.',
   {'slump': 'fresh', 'marshall': 'asph', 'charpy': 'tough', 'la': 'agg'},
   'Each material has a signature test. Wet concrete is checked for how easily it flows, asphalt for how it holds up when squeezed, metal for how it takes a sudden hit, and stone for how it wears.',
   'The slump test measures the workability of fresh concrete. The Marshall test measures the stability and flow of an asphalt mix. The Charpy test measures the energy a notched metal bar absorbs under impact. The Los Angeles abrasion test measures how well aggregate resists wear.',
   hb('Civil Engineering', 'Materials Science/Structure of Matter'), verify='reference', basis='Standard test methods: ASTM C143 (slump), ASTM D6927 (Marshall stability and flow), ASTM E23 (Charpy impact), ASTM C131 (Los Angeles abrasion)',
   units=None, tags=['test methods', 'slump', 'marshall', 'charpy'],
   tokens=ids([('slump', 'Slump test'), ('marshall', 'Marshall test'), ('charpy', 'Charpy test'), ('la', 'Los Angeles abrasion test')]),
   targets=[{'id': 'tough', 'label': 'Impact toughness of a metal'}, {'id': 'fresh', 'label': 'Workability of fresh concrete'}, {'id': 'agg', 'label': 'Wear resistance of aggregate'}, {'id': 'asph', 'label': 'Stability and flow of an asphalt mix'}]),
 q('materials-0004', 'materials-c', 'numeric', 'In a tension test, a steel bar reaches a stress of 140 MPa at a strain of 0.0007, still on the straight-line part of the curve. What is the modulus of elasticity?',
   num(200, 'GPa'), 'The modulus of elasticity is the stiffness of the material: how much stress it takes to produce a given stretch. It is the slope of the straight part of the stress-strain curve.',
   'E = \\frac{stress}{strain} = \\frac{140 MPa}{0.0007} = 200,000 MPa = 200 GPa.',
   hb('Mechanics of Materials', 'Materials Science/Structure of Matter'), tags=['modulus of elasticity', 'stress-strain']),
])
